import * as React from "react";

export type PlusCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function PlusCircleIcon({ size = 20, ...props }: PlusCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5"/><path d="M12 8.5v7M8.5 12h7"/>
    </svg>
  );
}
